import React, { useState } from "react";
import { Link } from "react-router-dom";
import "./StandaloneHeader.css";

const YRC_LOGO = "https://www.annauniv.edu/yrc/images/YRC.jpg";

export default function StandaloneHeader({ user, digitalId, onSignOut }) {
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  return (
    <header className="standalone-navbar-container">
      <div className="standalone-navbar">
        {/* Left branding */}
        <Link to="/portal" className="standalone-logo-section">
          <img src={YRC_LOGO} alt="YRC Logo" className="standalone-logo" />
          <div className="standalone-logo-text">
            <div className="standalone-title">
              SSN YRC <span className="standalone-badge">VOLUNTEER PORTAL</span>
            </div>
            <div className="standalone-subtitle">Youth Red Cross • Official Portal</div>
          </div>
        </Link>

        {/* Right actions (Desktop) */}
        <div className="standalone-actions-desktop">
          {user && (
            <div className="standalone-user-pill">
              <span className="user-icon">👤</span>
              <span className="user-email" title={user.email}>
                {digitalId ? `ID: ${digitalId}` : user.email}
              </span>
            </div>
          )}

          {user && onSignOut && (
            <button
              type="button"
              onClick={onSignOut}
              className="standalone-signout-btn"
              title="Sign out of volunteer account"
            >
              Sign Out
            </button>
          )}
        </div>

        {/* Mobile menu button */}
        <button
          className="standalone-menu-btn"
          onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
          aria-label="Toggle navigation menu"
        >
          {mobileMenuOpen ? "✖" : "☰"}
        </button>
      </div>

      {/* Mobile menu dropdown */}
      {mobileMenuOpen && (
        <div className="standalone-mobile-menu">
          {user && (
            <div className="standalone-mobile-user-info">
              <div>👤 <strong>{user.displayName || "Volunteer"}</strong></div>
              <div className="mobile-user-sub">{user.email}</div>
              {digitalId && <div className="mobile-user-id">Digital ID: {digitalId}</div>}
            </div>
          )}

          <Link
            to="/"
            className="standalone-mobile-link"
            onClick={() => setMobileMenuOpen(false)}
          >
            🌐 Visit Main YRC Website
          </Link>

          {user && onSignOut && (
            <button
              type="button"
              className="standalone-mobile-signout"
              onClick={() => {
                setMobileMenuOpen(false);
                onSignOut();
              }}
            >
              🚪 Sign Out
            </button>
          )}
        </div>
      )}
    </header>
  );
}
